```javascript
chrome.runtime.onMessageReceived.addListener((request, sender, sendResponse) => {
  if (request.action === 'takeScreenshot') {
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      chrome.tabs.sendMessage(tabs[0].id, { action: 'takeScreenshot' });
    });
  }
});
```

4. Open `content_script.js` and add the following content:

```javascript
chrome.runtime.onMessageReceived.addListener((request, sender, sendResponse) => {
  if (request.action === 'takeScreenshot') {
    chrome.tabs.captureVisibleTab(null, { format: 'png' }, (screenshot) => {
      const screenshotBlob = new Blob([screenshot], { type: 'image/png' });
      const downloadLink = document.createElement('a');
      downloadLink.href = URL.createObjectURL(screenshotBlob);
      downloadLink.download = `screenshot_${Date.now()}.png`;
      downloadLink.style.display = 'none';
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);
      URL.revokeObjectURL(downloadLink.href);
    });
  }
});
```

