ember install ember-cli-json-api
ember install ember-cli-web-worker
```

2. Create a new service for handling the CSV download:

```bash
touch app/services/csv-downloader.js
```

3. Implement the CSV downloader service:

```javascript
import Service from '@ember/service';
import { get } from '@ember/object';
import { inject as service } from '@ember/service';
import { A } from '@ember/array';
import { read } from 'csv-parser';
import { createReadStream } from 'fs';
import { promisify } from 'util';

const readFile = promisify(createReadStream);

export default Service.extend({
  store: service(),

  async downloadCSV(url) {
    const worker = new Worker('/assets/csv-downloader.js');

    worker.onmessage = (event) => {
      const records = event.data.map((record) => {
        return this.store.createRecord('csv-record', record);
      });

      this.store.pushPayload({
        data: {
          type: 'csv-records',
          records,
        },
      });
    };

    worker.postMessage({ url });
  },
});
```

4. Create a new web worker file for handling the CSV parsing:

```bash
touch assets/csv-downloader.js
```

5. Implement the CSV parsing in the web worker:

```javascript
self.onmessage = (event) => {
  const { url } = event.data;

  readFile(url, { encoding: 'utf8' })
    .then((data) => {
      return read(data, {
        columns: true,
        ls: true,
      });
    })
    .then((rows) => {
      self.postMessage(rows);
    })
    .catch((error) => {
      console.error(error);
      self.postMessage(null);
    });
};
```

6. Create a route for triggering the CSV download:

```bash
touch app/routes/csv-download.js
```

7. Implement the CSV download route:

```javascript
import Route from '@ember/routing/route';
import { inject as service } from '@ember/service';

export default class CsvDownloadRoute extends Route {
  @service csvDownloader;

  async model() {
    await this.csvDownloader.downloadCSV('https://example.com/csv-file.csv');
  }
}
```

To compare two Excel files and show discrepancies in Node.js, you can use a combination of libraries such as `xlsx` for reading Excel files and `lodash` for comparing arrays. Here's a basic example:

1. First, install the necessary libraries:

```bash
npm install xlsx lodash
```

2. Create a new file, let's call it `compareExcel.js`.

3. Write the following code:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareExcelFiles(file1, file2, sheetName) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet1 = workbook1.Sheets[sheetName];
  const sheet2 = workbook2.Sheets[sheetName];

  const keys1 = _.keys(sheet1);
  const keys2 = _.keys(sheet2);

  const commonKeys = _.intersection(keys1, keys2);

  const data1 = commonKeys.map(key => sheet1[key].v);
  const data2 = commonKeys.map(key => sheet2[key].v);

  const differences = _.differenceWith(data1, data2, _.isEqual);

  return differences;
}

// Usage
const file1 = 'file1.xlsx';
const file2 = 'file2.xlsx';
const sheetName = 'Sheet1';

const differences = compareExcelFiles(file1, file2, sheetName);

console.log(differences);
```

This script reads two Excel files, selects a specific sheet, and compares the values in each row. If there are any differences, it will log them to the console.

Please note that this example assumes that the Excel files have the same structure (same number of columns and the same order of columns). If the files have different structures, you may need to adjust the script accordingly.

Also, this script does not handle differences in formatting or data types. If you need to handle those, you may need to use a more advanced library or write more complex comparison logic.

Lastly, remember to replace `file1`, `file2`, and `sheetName` with the paths and names of your actual Excel files and sheets.

